package dev.mopu.multiscreen;
import android.app.Activity;import android.os.*;import android.widget.*;import android.view.*;import android.graphics.*;import org.json.*;import java.net.*;import java.io.*;
public class Panel extends Activity {
 int selected=0;boolean active=false;Handler timer=new Handler();ImageView image;TextView status;Bitmap bitmap;JSONObject chosen;long epoch=0;
 public void onCreate(Bundle b){super.onCreate(b);selected=getIntent().getIntExtra("display",0);getWindow().setStatusBarColor(0xfff5f7fa);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);render();}
 public void onNewIntent(android.content.Intent in){super.onNewIntent(in);setIntent(in);selected=in.getIntExtra("display",0);render();}
 public void onResume(){super.onResume();active=true;render();}
 public void onPause(){active=false;super.onPause();}
 void button(LinearLayout l,String t,Runnable f){Button b=new Button(this);b.setText(t);b.setOnClickListener(v->{f.run();render();});l.addView(b);}
 TextView label(LinearLayout l,String text,int size){TextView t=new TextView(this);t.setText(text);t.setTextColor(0xff182b3c);t.setTextSize(size);l.addView(t);return t;}
 void render(){epoch++;chosen=null;image=null;LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,100,24,35);l.setBackgroundColor(0xfff5f7fa);setContentView(l);
 try{JSONArray a=Bridge.screens(this);for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==selected)chosen=a.getJSONObject(i);
 if(chosen!=null){int id=selected;label(l,"副屏 "+id+" / "+chosen.optString("app"),22);status=label(l,chosen.optString("step"),15);button(l,"返回全部任务",()->selected=0);button(l,Bridge.blocked(this,id)?"交还这个副屏":"接管这个副屏",()->Bridge.pause(this,id,!Bridge.blocked(this,id)));
 image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);l.addView(image,new LinearLayout.LayoutParams(-1,0,1));image.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP&&bitmap!=null){if(!Bridge.blocked(this,id)){status.setText("先接管这个副屏，再操作画面");return true;}float scale=Math.min((float)image.getWidth()/bitmap.getWidth(),(float)image.getHeight()/bitmap.getHeight());float left=(image.getWidth()-bitmap.getWidth()*scale)/2;float top=(image.getHeight()-bitmap.getHeight()*scale)/2;int x=(int)((e.getX()-left)/scale),y=(int)((e.getY()-top)/scale);if(x>=0&&y>=0&&x<bitmap.getWidth()&&y<bitmap.getHeight())try{send(new JSONObject().put("op","tap").put("x",x).put("y",y));}catch(Exception ex){} }return true;});
 }else{selected=0;label(l,"副屏实验台",26);label(l,"主屏 0 · 留给你使用",18);button(l,"接管全部",()->Bridge.pause(this,-1,true));button(l,"交还全部",()->{Bridge.pause(this,-1,false);try{JSONArray all=Bridge.screens(this);for(int i=0;i<all.length();i++)Bridge.pause(this,all.getJSONObject(i).getInt("id"),false);}catch(Exception e){}});
 ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);l.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);int id=x.getInt("id");label(list,"\n副屏 "+id+" / "+x.optString("app")+"\n"+x.optString("step")+" · "+(Bridge.blocked(this,id)?"已接管":x.optString("status")),18);button(list,"查看副屏 "+id,()->selected=id);button(list,Bridge.blocked(this,id)?"交还副屏 "+id:"接管副屏 "+id,()->Bridge.pause(this,id,!Bridge.blocked(this,id)));}}
 }catch(Exception e){label(l,e.toString(),16);}if(active)refresh(epoch);
 }
 void refresh(long e){if(!active||chosen==null||image==null||epoch!=e)return;String url=chosen.optString("viewer");new Thread(()->{Bitmap b=null;try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(1500);c.setReadTimeout(5000);try(InputStream in=c.getInputStream()){b=BitmapFactory.decodeStream(in);}c.disconnect();}catch(Exception ex){}final Bitmap result=b;runOnUiThread(()->{if(epoch!=e||!active)return;if(result!=null){bitmap=result;image.setImageBitmap(result);}else status.setText("画面连接已停止，请查看任务状态");timer.postDelayed(()->refresh(e),1000);});}).start();}
 void send(JSONObject q){if(chosen==null)return;String url=chosen.optString("human_url");long e=epoch;new Thread(()->{String result;try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(2000);c.setReadTimeout(12000);c.setDoOutput(true);byte[] body=q.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(body.length);try(OutputStream o=c.getOutputStream()){o.write(body);}result=c.getResponseCode()==200?"操作已发送，等待画面核对":"操作被拒绝：请先接管或检查连接";c.disconnect();}catch(Exception ex){result="连接已停止";}final String text=result;runOnUiThread(()->{if(epoch==e&&status!=null)status.setText(text);});}).start();}
}
